    width: 960px;
    margin: auto;
    font-size: 16px;
}

h2 {
    color: #185468 !important;
    font-family: 'Barlow Condensed';
    font-style: normal;
    font-weight: 500;
    font-size: 34px;
    line-height: 1.5em;
    margin-bottom: 45px;
}


.information {
    width: 70%;
    display: inline-block;
}


.byor-logo {
    width: 200px;
    margin-left: -20px;
    float: left;
    margin-right: 20px;
}

.links {
    position: absolute;
    top: 115px;
    right: 0;
    width: 25%;
    background-color: #185468;
    color: #ffffff;
    padding: 25px;
    border-radius: 5px;
}
.notice a {
color: #a8d4d8 !important;
}

.notice-header {
    color: #ffffff !important;
